composition.dart<pre><code>import 'package:flutter/material.dart';

/// Counts how many times each widget's build ran, for the test.
final buildCounts = &lt;String, int&gt;{};
void _count(String name) =&gt; buildCounts[name] = (buildCounts[name] ?? 0) + 1;

class ProfileCard extends StatelessWidget {
  const ProfileCard({super.key, required this.name, required this.role, this.online = false});

  final String name;
  final String role;
  final bool online;

  @override
  Widget build(BuildContext context) {
    _count('ProfileCard');
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Row(
          children: [
            Avatar(initials: name.substring(0, 1), online: online),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(name, style: Theme.of(context).textTheme.titleMedium),
                  Text(role),
                ],
              ),
            ),
            const CardMenuIcon(), // const: identical every time
          ],
        ),
      ),
    );
  }
}

class Avatar extends StatelessWidget {
  const Avatar({super.key, required this.initials, required this.online});
  final String initials;
  final bool online;

  @override
  Widget build(BuildContext context) {
    _count('Avatar');
    return Badge(
      isLabelVisible: online,
      smallSize: 10,
      child: CircleAvatar(child: Text(initials)),
    );
  }
}

class CardMenuIcon extends StatelessWidget {
  const CardMenuIcon({super.key});

  @override
  Widget build(BuildContext context) {
    _count('CardMenuIcon');
    return const Icon(Icons.more_vert);
  }
}

/// A parent that rebuilds when a button is pressed.
class Team extends StatefulWidget {
  const Team({super.key});
  @override
  State&lt;Team&gt; createState() =&gt; _TeamState();
}

class _TeamState extends State&lt;Team&gt; {
  bool _adaOnline = false;

  // A helper *method*: runs as part of _TeamState.build, can never be skipped.
  Widget _header() {
    _count('_header method');
    return const Text('Team');
  }

  @override
  Widget build(BuildContext context) {
    _count('Team');
    return Column(
      children: [
        _header(),
        ProfileCard(name: 'Ada', role: 'Engineer', online: _adaOnline),
        const ProfileCard(name: 'Grace', role: 'Admiral'),
        TextButton(
          onPressed: () =&gt; setState(() =&gt; _adaOnline = !_adaOnline),
          child: const Text('Toggle Ada'),
        ),
      ],
    );
  }
}
</code></pre> <p><code>ProfileCard</code> composes <code>Card</code>, <code>Padding</code>, <code>Row</code>, <code>Expanded</code>, <code>Column</code>, <code>Text</code> and two of our own widgets. <code>Team</code> is a stateful parent (stateful widgets are lesson 05) that toggles whether Ada is online. A global <code>buildCounts</code> map records each <code>build</code> call — a debugging trick for this lesson, not production code.</p> <p>Some framework widgets worth recognising from the code:</p> Widget Job <code>Card</code> Material surface with elevation and rounded corners <code>Padding</code> Insets its child <code>Row</code> / <code>Column</code> Lay children out horizontally / vertically <code>Expanded</code> Makes a <code>Row</code>/<code>Column</code> child take the remaining space <code>SizedBox</code> A fixed-size box — here, a 12-pixel gap <code>CircleAvatar</code>, <code>Badge</code>, <code>Icon</code> Material visuals

composition_test.dart<pre><code>import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hello/l1/composition.dart';

void main() {
  testWidgets('which builds run when the parent rebuilds', (tester) async {
    await tester.pumpWidget(const MaterialApp(home: Scaffold(body: Team())));
    print('first frame:  $buildCounts');

    buildCounts.clear();
    await tester.tap(find.text('Toggle Ada'));
    await tester.pump();
    print('after toggle: $buildCounts');

    expect(find.text('Ada'), findsOneWidget);
    expect(find.byType(ProfileCard), findsNWidgets(2));
  });
}
</code></pre> <pre><code>$ flutter test test/l1/composition_test.dart
first frame:  {Team: 1, _header method: 1, ProfileCard: 2, Avatar: 2, CardMenuIcon: 2}
after toggle: {Team: 1, _header method: 1, ProfileCard: 1, Avatar: 1}
00:00 +1: All tests passed!
</code></pre> <p>On the first frame everything builds once per instance — two cards, two avatars, two menu icons. After tapping "Toggle Ada", <code>Team</code> rebuilt, and then:</p> <ul> <li>Ada's <code>ProfileCard</code> and <code>Avatar</code> rebuilt — they're created with <code>online: _adaOnline</code>, a value   that changed, so Flutter has a new widget to apply.</li> <li>Grace's <code>ProfileCard</code> did not rebuild. It's written <code>const ProfileCard(...)</code>. A <code>const</code>   expression evaluates to the same object every time, so when Flutter compares the old widget to   the new one and finds them identical, it skips that whole subtree.</li> <li>No <code>CardMenuIcon</code> rebuilt, even inside Ada's rebuilt card, for the same reason: <code>const   CardMenuIcon()</code> is the same instance on every build.</li> <li><code>_header</code> ran again. It's a method on <code>_TeamState</code>, so it's just part of <code>Team.build</code>; it can   never be skipped independently. Had it been a <code>const Header()</code> widget, it would have been skipped   like the menu icon.</li> </ul> <p>This is the measurable reason behind two pieces of standard Flutter advice: use <code>const</code> wherever you can, and prefer small widget classes over helper methods that return widgets. Widget classes also get their own <code>BuildContext</code>, can be <code>const</code>, and show up by name in the inspector and in tests (<code>find.byType(Avatar)</code>).</p> <p>Don't over-apply it, though. Rebuilding a few <code>Text</code> and <code>Padding</code> widgets costs microseconds; Flutter is designed for it. The point of <code>const</code> and extraction is to keep rebuilds proportional to what changed as screens grow, not to eliminate every <code>build</code> call.</p>

layout_test.dart<pre><code>import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

/// Pumps [child] at the root of an 800x600 test screen and reports
/// the constraints it received and the size it chose.
Future&lt;void&gt; probe(WidgetTester tester, String label, Widget child) async {
  final key = GlobalKey();
  await tester.pumpWidget(Directionality(
    textDirection: TextDirection.ltr,
    child: KeyedSubtree(key: key, child: child),
  ));
  // Measure the innermost box: the blue ColoredBox.
  final target = tester.renderObject&lt;RenderBox&gt;(find.byType(ColoredBox));
  final err = tester.takeException();
  print('${label.padRight(44)} constraints=${target.constraints}  size=${target.size}'
      '${err != null ? '  EXCEPTION: ${err.toString().split('\n').first}' : ''}');
}

void main() {
  testWidgets('constraints go down, sizes go up', (tester) async {
    const blue = ColoredBox(color: Colors.blue);
    await probe(tester, 'root: SizedBox(100x100)', const SizedBox(width: 100, height: 100, child: blue));
    await probe(tester, 'root: Center &gt; SizedBox(100x100)',
        const Center(child: SizedBox(width: 100, height: 100, child: blue)));
    await probe(tester, 'Center &gt; SizedBox(2000x50)',
        const Center(child: SizedBox(width: 2000, height: 50, child: blue)));
    await probe(tester, 'Center &gt; ConstrainedBox(min 300x300) &gt; 100x100',
        Center(child: ConstrainedBox(constraints: const BoxConstraints(minWidth: 300, minHeight: 300),
            child: SizedBox(width: 100, height: 100, child: blue))));
    await probe(tester, 'Center &gt; UnconstrainedBox &gt; 2000x50',
        const Center(child: UnconstrainedBox(child: SizedBox(width: 2000, height: 50, child: blue))));
  });

  testWidgets('what each child is told', (tester) async {
    final seen = &lt;String, BoxConstraints&gt;{};
    Widget spy(String name, Widget child) =&gt; LayoutBuilder(builder: (context, c) {
          seen[name] = c;
          return child;
        });

    await tester.pumpWidget(Directionality(
      textDirection: TextDirection.ltr,
      child: spy('root', Center(
        child: spy('inside Center', Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            spy('Column child', const SizedBox(width: 50, height: 20)),
            SizedBox(width: 300, child: Row(children: [
              spy('Row child', const SizedBox(width: 40, height: 20)),
              Expanded(child: spy('Expanded in Row', const SizedBox(height: 20))),
            ])),
            SizedBox(height: 100, child: spy('ListView parent', const SizedBox())),
          ],
        )),
      )),
    ));
    seen.forEach((k, v) =&gt; print('${k.padRight(18)} $v'));
  });

  testWidgets('the classic overflow', (tester) async {
    await tester.pumpWidget(const Directionality(
      textDirection: TextDirection.ltr,
      child: Center(
        child: SizedBox(
          width: 200,
          child: Row(children: [
            Text('A very long title that does not fit in two hundred pixels'),
          ]),
        ),
      ),
    ));
    final e = tester.takeException();
    print('Row with long Text: ${e.toString().split('\n').first}');

    await tester.pumpWidget(const Directionality(
      textDirection: TextDirection.ltr,
      child: Center(
        child: SizedBox(
          width: 200,
          child: Row(children: [
            Expanded(child: Text('A very long title that does not fit in two hundred pixels',
                overflow: TextOverflow.ellipsis)),
          ]),
        ),
      ),
    ));
    print('with Expanded + ellipsis: exception=${tester.takeException()}');
  });

  testWidgets('unbounded height', (tester) async {
    await tester.pumpWidget(Directionality(
      textDirection: TextDirection.ltr,
      child: Column(children: [
        ListView(children: const [Text('a'), Text('b')]),
      ]),
    ));
    final e = tester.takeException();
    print('ListView in Column: ${e.toString().split('\n').first}');
  });

  testWidgets('bounded fix', (tester) async {
    await tester.pumpWidget(Directionality(
      textDirection: TextDirection.ltr,
      child: Column(children: [
        Expanded(child: ListView(children: const [Text('a'), Text('b')])),
      ]),
    ));
    print('ListView in Expanded in Column: exception=${tester.takeException()}');
  });
}
</code></pre> <p>Two tools do the measuring. <code>probe</code> pumps a widget at the root of the 800 × 600 test screen and reads the innermost <code>ColoredBox</code>'s render object: its <code>constraints</code> (what it was told) and its <code>size</code> (what it chose). <code>spy</code> wraps a <code>LayoutBuilder</code> around a child, which receives the constraints that position in the tree is given.</p>

lifecycle.dart<pre><code>import 'dart:async';
import 'package:flutter/material.dart';

final lifecycleLog = &lt;String&gt;[];

/// A countdown that ticks once per second and reports each lifecycle call.
class Countdown extends StatefulWidget {
  const Countdown({super.key, required this.from, this.onDone});
  final int from;
  final VoidCallback? onDone;

  @override
  State&lt;Countdown&gt; createState() {
    lifecycleLog.add('createState');
    return _CountdownState();
  }
}

class _CountdownState extends State&lt;Countdown&gt; {
  late int _remaining;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    lifecycleLog.add('initState(from=${widget.from})');
    _remaining = widget.from;
    _timer = Timer.periodic(const Duration(seconds: 1), (_) =&gt; _tick());
  }

  void _tick() {
    setState(() =&gt; _remaining--);
    if (_remaining == 0) {
      _timer?.cancel();
      widget.onDone?.call();
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    lifecycleLog.add('didChangeDependencies');
  }

  @override
  void didUpdateWidget(Countdown oldWidget) {
    super.didUpdateWidget(oldWidget);
    lifecycleLog.add('didUpdateWidget(${oldWidget.from} -&gt; ${widget.from})');
    if (oldWidget.from != widget.from) {
      _remaining = widget.from; // parent asked for a new countdown
    }
  }

  @override
  void dispose() {
    lifecycleLog.add('dispose');
    _timer?.cancel(); // without this, the timer keeps calling setState on a dead State
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    lifecycleLog.add('build($_remaining)');
    return Text('$_remaining', style: Theme.of(context).textTheme.displaySmall);
  }
}
</code></pre> <p>The structure to memorise:</p> <ul> <li><code>Countdown</code> (the widget) holds configuration: <code>from</code> and <code>onDone</code>. It's <code>const</code>-constructible and   immutable.</li> <li><code>createState()</code> creates the <code>_CountdownState</code> — once per place in the tree, not once per build.   (Logging inside <code>createState</code> is only for this demonstration; <code>flutter analyze</code> flags it with   <code>no_logic_in_create_state</code>, and real code should do nothing there but return the state.)</li> <li><code>_CountdownState</code> holds <code>_remaining</code> and the <code>Timer</code>. It reads its widget's configuration through   the <code>widget</code> getter.</li> <li><code>setState(fn)</code> runs <code>fn</code> to change fields and schedules a rebuild. It doesn't rebuild   immediately.</li> </ul>

lifecycle_test.dart<pre><code>import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hello/l1/lifecycle.dart';

Widget app(Widget child) =&gt; MaterialApp(home: Scaffold(body: Center(child: child)));

void main() {
  setUp(lifecycleLog.clear);

  testWidgets('lifecycle of a State', (tester) async {
    var done = false;
    await tester.pumpWidget(app(Countdown(from: 3, onDone: () =&gt; done = true)));
    print('mount:          $lifecycleLog'); lifecycleLog.clear();

    await tester.pump(const Duration(seconds: 1));
    print('after 1s:       $lifecycleLog  text=${(tester.widget&lt;Text&gt;(find.byType(Text))).data}');
    lifecycleLog.clear();

    // Parent rebuilds with new configuration: same State, didUpdateWidget.
    await tester.pumpWidget(app(Countdown(from: 5, onDone: () =&gt; done = true)));
    print('new config:     $lifecycleLog'); lifecycleLog.clear();

    await tester.pump(const Duration(seconds: 5));
    print('after 5s more:  $lifecycleLog  done=$done'); lifecycleLog.clear();

    // Removing the widget disposes the State.
    await tester.pumpWidget(app(const SizedBox()));
    print('removed:        $lifecycleLog');
  });

  testWidgets('different type at the same spot = new State', (tester) async {
    await tester.pumpWidget(app(const Countdown(from: 3)));
    lifecycleLog.clear();
    await tester.pumpWidget(app(const Padding(padding: EdgeInsets.zero, child: Countdown(from: 3))));
    print('wrapped in Padding: $lifecycleLog');
    await tester.pumpWidget(app(const SizedBox()));
  });
}
</code></pre> <pre><code>$ flutter test test/l1/lifecycle_test.dart
mount:          [createState, initState(from=3), didChangeDependencies, build(3)]
after 1s:       [build(2)]  text=2
new config:     [didUpdateWidget(3 -&gt; 5), build(5)]
after 5s more:  [build(0)]  done=true
removed:        [dispose]
wrapped in Padding: [createState, initState(from=3), didChangeDependencies, build(3), dispose]
00:00 +2: All tests passed!
</code></pre> <p>(<code>tester.pump(duration)</code> advances the test's fake clock, so timers fire instantly — a five-second countdown takes milliseconds to test.)</p> Call When Use it for <code>createState</code> widget inserted at a new place creating the <code>State</code> (nothing else) <code>initState</code> once, right after creation one-time setup: controllers, timers, subscriptions <code>didChangeDependencies</code> after <code>initState</code>, and whenever an inherited widget it depends on changes work that needs <code>Theme.of</code>, <code>MediaQuery.of</code>, etc. <code>build</code> every time the state is dirty or its parent rebuilds describing UI — nothing else <code>didUpdateWidget</code> parent rebuilt with a new widget of the same type reacting to changed configuration <code>dispose</code> permanently removed cancel timers, close streams, dispose controllers <p>Four observations from the run:</p> <ol> <li>New configuration keeps the same <code>State</code>. When the parent pumped <code>Countdown(from: 5)</code>,    Flutter didn't create a new state; it called <code>didUpdateWidget(3 -&gt; 5)</code>. If the state had ignored    that, the countdown would have kept counting from 2. Whenever a field derived from <code>widget</code> should    follow changes, handle <code>didUpdateWidget</code>.</li> <li>Several <code>setState</code> calls, one build. Advancing five seconds fired the timer five times, each    calling <code>setState</code>, but only one <code>build(0)</code> was logged. <code>setState</code> marks the state dirty; the    rebuild happens once, at the next frame. You never need to "batch" <code>setState</code> calls yourself.</li> <li><code>dispose</code> on removal. Replacing the countdown with a <code>SizedBox</code> disposed its state.</li> <li>Changing the tree's shape loses state. Wrapping the same <code>Countdown</code> in a <code>Padding</code> created a    new state (<code>createState</code>, <code>initState</code> …) and disposed the old one. At that position the old    element was a <code>Countdown</code>, the new widget is a <code>Padding</code> — different types — so the subtree was    rebuilt from scratch. Conditional wrappers (<code>showBorder ? Padding(child: x) : x</code>) silently reset    state for exactly this reason; lesson 07 shows how keys interact with it.</li> </ol>

signup_form.dart<pre><code>import 'package:flutter/material.dart';

/// Validators are top-level functions so they can be unit-tested without widgets.
String? validateEmail(String? v) {
  final value = v?.trim() ?? '';
  if (value.isEmpty) return 'Enter your email';
  if (!RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$').hasMatch(value)) return 'That email looks incomplete';
  return null;
}

String? validateAge(String? v) {
  final n = int.tryParse(v?.trim() ?? '');
  if (n == null) return 'Enter a whole number';
  if (n &lt; 13) return 'You must be 13 or older';
  if (n &gt; 120) return 'Check the age';
  return null;
}

class SignupData {
  const SignupData(this.email, this.age);
  final String email;
  final int age;
}

class SignupForm extends StatefulWidget {
  const SignupForm({super.key, required this.onSubmit});
  final ValueChanged&lt;SignupData&gt; onSubmit;

  @override
  State&lt;SignupForm&gt; createState() =&gt; _SignupFormState();
}

class _SignupFormState extends State&lt;SignupForm&gt; {
  final _formKey = GlobalKey&lt;FormState&gt;();
  final _email = TextEditingController();
  final _age = TextEditingController();
  final _ageFocus = FocusNode();
  bool _agreed = false;

  @override
  void dispose() {
    _email.dispose();
    _age.dispose();
    _ageFocus.dispose();
    super.dispose();
  }

  void _submit() {
    final ok = _formKey.currentState!.validate();
    if (!ok || !_agreed) {
      if (!_agreed) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please accept the terms')));
      }
      return;
    }
    widget.onSubmit(SignupData(_email.text.trim(), int.parse(_age.text.trim())));
  }

  @override
  Widget build(BuildContext context) {
    return Form(
      key: _formKey,
      autovalidateMode: AutovalidateMode.onUserInteractionIfError,
      child: Column(
        children: [
          TextFormField(
            key: const Key('email'),
            controller: _email,
            decoration: const InputDecoration(labelText: 'Email'),
            keyboardType: TextInputType.emailAddress,
            textInputAction: TextInputAction.next,
            autofillHints: const [AutofillHints.email],
            validator: validateEmail,
            onFieldSubmitted: (_) =&gt; _ageFocus.requestFocus(),
          ),
          TextFormField(
            key: const Key('age'),
            controller: _age,
            focusNode: _ageFocus,
            decoration: const InputDecoration(labelText: 'Age'),
            keyboardType: TextInputType.number,
            textInputAction: TextInputAction.done,
            validator: validateAge,
            onFieldSubmitted: (_) =&gt; _submit(),
          ),
          CheckboxListTile(
            value: _agreed,
            onChanged: (v) =&gt; setState(() =&gt; _agreed = v ?? false),
            title: const Text('I accept the terms'),
          ),
          FilledButton(onPressed: _submit, child: const Text('Create account')),
        ],
      ),
    );
  }
}
</code></pre> <p>The moving parts:</p> <ul> <li><code>TextEditingController</code> holds a field's text and selection. You read <code>_email.text</code> on submit,   and you can set it to pre-fill or clear. Controllers own resources, so they're created once (as   fields of the <code>State</code>) and disposed in <code>dispose</code> — the lifecycle rule from   lesson 05.</li> <li><code>Form</code> + <code>GlobalKey&lt;FormState&gt;</code> groups fields. <code>_formKey.currentState!.validate()</code> runs every   field's <code>validator</code>, shows the messages, and returns whether all passed.</li> <li>Validators take the current text and return an error message, or <code>null</code> for valid. They're   top-level functions here so they can be unit-tested without building any widgets.</li> <li><code>autovalidateMode: AutovalidateMode.onUserInteractionIfError</code> — fields aren't nagged while the   user is first typing, but once a field has shown an error, it re-validates as they edit, so the   error disappears the moment it's fixed.</li> <li>Keyboard behaviour: <code>keyboardType</code> picks the on-screen keyboard (email layout, number pad),   <code>textInputAction</code> sets the action key's label and behaviour (next, done), <code>onFieldSubmitted</code>   reacts to it, and a <code>FocusNode</code> lets the email field move focus to the age field.</li> <li><code>autofillHints</code> let the platform's password manager offer the user's email.</li> <li>The terms checkbox isn't a form field, so the submit handler checks it separately and shows a   <code>SnackBar</code>.</li> </ul>

signup_form_test.dart<pre><code>import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hello/l1/signup_form.dart';

void main() {
  late List&lt;SignupData&gt; submitted;
  Future&lt;void&gt; pumpForm(WidgetTester tester) async {
    submitted = [];
    await tester.pumpWidget(MaterialApp(
      home: Scaffold(body: SignupForm(onSubmit: submitted.add)),
    ));
  }

  List&lt;String&gt; errorTexts(WidgetTester tester) =&gt; tester
      .widgetList&lt;Text&gt;(find.byType(Text))
      .map((t) =&gt; t.data ?? '')
      .where((s) =&gt; s.startsWith('Enter') || s.contains('must') || s.contains('looks'))
      .toList();

  testWidgets('empty submit shows every error at once', (tester) async {
    await pumpForm(tester);
    await tester.tap(find.text('Create account'));
    await tester.pump();
    print('errors: ${errorTexts(tester)}');
    expect(submitted, isEmpty);
  });

  testWidgets('errors update as the user fixes them', (tester) async {
    await pumpForm(tester);
    await tester.enterText(find.byKey(const Key('email')), 'ada@');
    await tester.enterText(find.byKey(const Key('age')), '9');
    await tester.tap(find.text('Create account'));
    await tester.pump();
    print('first try:  ${errorTexts(tester)}');
    await tester.enterText(find.byKey(const Key('email')), 'ada@example.com');
    await tester.pump();
    print('email fixed: ${errorTexts(tester)}');
  });

  testWidgets('valid input needs the checkbox too', (tester) async {
    await pumpForm(tester);
    await tester.enterText(find.byKey(const Key('email')), '  ada@example.com ');
    await tester.enterText(find.byKey(const Key('age')), '36');
    await tester.tap(find.text('Create account'));
    await tester.pump();
    print('snackbar shown: ${find.text('Please accept the terms').evaluate().isNotEmpty}');
    await tester.tap(find.text('I accept the terms'));
    await tester.pump();
    await tester.tap(find.text('Create account'));
    await tester.pump();
    print('submitted: ${submitted.map((d) =&gt; '${d.email}/${d.age}').toList()}');
  });

  testWidgets('keyboard "next" moves focus to age, "done" submits', (tester) async {
    await pumpForm(tester);
    await tester.tap(find.byKey(const Key('email')));
    await tester.enterText(find.byKey(const Key('email')), 'grace@example.com');
    await tester.testTextInput.receiveAction(TextInputAction.next);
    await tester.pump();
    final ageField = tester.widget&lt;EditableText&gt;(find.descendant(of: find.byKey(const Key('age')), matching: find.byType(EditableText)));
    print('age focused after next: ${ageField.focusNode.hasFocus}');
  });

  test('validators are plain functions', () {
    expect(validateEmail(' a@b.co '), isNull);
    expect(validateEmail('a@b'), 'That email looks incomplete');
    expect(validateAge('130'), 'Check the age');
    expect(validateAge('13'), isNull);
  });
}
