async_demo.dart<pre><code>import 'dart:async';
import 'package:flutter/material.dart';

Future&lt;String&gt; fetchQuote({bool fail = false}) async {
  await Future&lt;void&gt;.delayed(const Duration(seconds: 1));
  if (fail) throw TimeoutException('quote server did not answer');
  return 'Simplicity is prerequisite for reliability.';
}

class QuoteCard extends StatefulWidget {
  const QuoteCard({super.key, this.fail = false});
  final bool fail;
  @override
  State&lt;QuoteCard&gt; createState() =&gt; _QuoteCardState();
}

class _QuoteCardState extends State&lt;QuoteCard&gt; {
  // Created once, in initState — NOT in build.
  late Future&lt;String&gt; _quote = fetchQuote(fail: widget.fail);

  void _retry() {
    // Block body on purpose: `setState(() =&gt; _quote = ...)` would return the Future
    // from the closure, and setState asserts against that.
    setState(() {
      _quote = fetchQuote();
    });
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder&lt;String&gt;(
      future: _quote,
      builder: (context, snapshot) {
        if (snapshot.connectionState != ConnectionState.done) {
          return const CircularProgressIndicator();
        }
        if (snapshot.hasError) {
          return Column(children: [
            Text('Error: ${snapshot.error}'),
            TextButton(onPressed: _retry, child: const Text('Retry')),
          ]);
        }
        return Text(snapshot.data!);
      },
    );
  }
}

/// A countdown as a Stream.
Stream&lt;int&gt; countdown(int from) async* {
  for (var i = from; i &gt;= 0; i--) {
    yield i;
    if (i &gt; 0) await Future&lt;void&gt;.delayed(const Duration(seconds: 1));
  }
}

class CountdownView extends StatefulWidget {
  const CountdownView({super.key});
  @override
  State&lt;CountdownView&gt; createState() =&gt; _CountdownViewState();
}

class _CountdownViewState extends State&lt;CountdownView&gt; {
  final _ticks = countdown(3);
  @override
  Widget build(BuildContext context) =&gt; StreamBuilder&lt;int&gt;(
        stream: _ticks,
        builder: (context, snap) =&gt; Text(switch (snap) {
          AsyncSnapshot(connectionState: ConnectionState.waiting) =&gt; 'waiting',
          AsyncSnapshot(connectionState: ConnectionState.done, :final data) =&gt; 'liftoff (last value $data)',
          AsyncSnapshot(:final data?) =&gt; 'T-$data',
          _ =&gt; '?',
        }, key: const Key('cd')),
      );
}

/// The bug version: a new Future on every build.
class LeakyQuote extends StatelessWidget {
  const LeakyQuote({super.key, required this.onFetch});
  final VoidCallback onFetch;
  @override
  Widget build(BuildContext context) =&gt; FutureBuilder&lt;String&gt;(
        future: () {
          onFetch();
          return fetchQuote();
        }(),
        builder: (context, s) =&gt; Text(s.data ?? 'loading'),
      );
}
</code></pre> <p>Things to notice in <code>QuoteCard</code>:</p> <ul> <li>The future is created once, by a <code>late</code> field initializer on the <code>State</code>. A <code>late</code> field is initialized on   first access — here, the first <code>build</code> — and then kept for the life of the <code>State</code>, so later rebuilds reuse the   same future. (Assigning it in <code>initState</code> is equivalent and more explicit.) It isn't created inside <code>build</code>.</li> <li><code>connectionState != done</code> covers both "waiting" and the moment between frames; error is checked before data.</li> <li>Retry assigns a new future inside <code>setState</code>. <code>FutureBuilder</code> notices the different future and starts over   from <code>waiting</code>.</li> </ul> <p><code>CountdownView</code> uses <code>async*</code> to produce a stream and a Dart 3 <code>switch</code> on the snapshot's fields to pick the label.</p>

