api_client.dart<pre><code>import 'dart:convert';
import 'package:http/http.dart' as http;

class Book {
  const Book({required this.id, required this.title, required this.author, this.year});
  final int id;
  final String title;
  final String author;
  final int? year;

  /// Validates while parsing: a malformed payload fails here, not deep in the UI.
  factory Book.fromJson(Map&lt;String, dynamic&gt; json) {
    return switch (json) {
      {'id': int id, 'title': String title, 'author': String author} =&gt;
        Book(id: id, title: title, author: author, year: json['year'] as int?),
      _ =&gt; throw FormatException('Not a book: $json'),
    };
  }

  Map&lt;String, dynamic&gt; toJson() =&gt; {'id': id, 'title': title, 'author': author, if (year != null) 'year': year};

  @override
  String toString() =&gt; 'Book($id, $title, $author, ${year ?? '-'})';
}

/// One exception type for callers to handle.
class ApiException implements Exception {
  ApiException(this.message, {this.statusCode});
  final String message;
  final int? statusCode;
  @override
  String toString() =&gt; 'ApiException(${statusCode ?? '-'}): $message';
}

class BooksApi {
  BooksApi({http.Client? client, Uri? baseUrl})
      : _client = client ?? http.Client(),
        _base = baseUrl ?? Uri.parse('https://api.example.com/');
  final http.Client _client;
  final Uri _base;

  Future&lt;List&lt;Book&gt;&gt; list({String? query}) async {
    final uri = _base.resolve('books').replace(queryParameters: {if (query != null) 'q': query});
    final res = await _send(() =&gt; _client.get(uri, headers: {'Accept': 'application/json'}));
    final body = jsonDecode(res.body);
    if (body is! List) throw ApiException('Expected a JSON array');
    return body.map((e) =&gt; Book.fromJson(e as Map&lt;String, dynamic&gt;)).toList();
  }

  Future&lt;Book&gt; create(String title, String author) async {
    final res = await _send(() =&gt; _client.post(
          _base.resolve('books'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({'title': title, 'author': author}),
        ));
    return Book.fromJson(jsonDecode(res.body) as Map&lt;String, dynamic&gt;);
  }

  Future&lt;http.Response&gt; _send(Future&lt;http.Response&gt; Function() request) async {
    final http.Response res;
    try {
      res = await request().timeout(const Duration(seconds: 10));
    } on Exception catch (e) {
      throw ApiException('Network error: $e');
    }
    if (res.statusCode &lt; 200 || res.statusCode &gt;= 300) {
      throw ApiException('HTTP ${res.statusCode}', statusCode: res.statusCode);
    }
    return res;
  }

  void close() =&gt; _client.close();
}
</code></pre> <p>Design decisions worth copying:</p> <ul> <li>The <code>http.Client</code> is injected. Production uses a real <code>http.Client()</code>; tests pass a <code>MockClient</code>. A client   also reuses connections across requests, which a bare <code>http.get(...)</code> call doesn't, and should be <code>close()</code>d   when you're done with it.</li> <li>URLs are built with <code>Uri</code>, never string concatenation. <code>replace(queryParameters: ...)</code> encodes values for you   (the space in <code>du ne</code> becomes <code>+</code>).</li> <li><code>fromJson</code> validates. The Dart 3 map pattern <code>{'id': int id, 'title': String title, ...}</code> matches only if the   keys exist and have the right types, binding them to variables in one step. Anything else throws a   <code>FormatException</code> right at the boundary instead of a confusing <code>type 'String' is not a subtype of type 'int'</code>   three screens later.</li> <li>One choke point (<code>_send</code>) applies the timeout, maps transport errors and non-2xx statuses to   <code>ApiException</code>, and keeps each endpoint method short.</li> </ul>

persistence_demo.dart (notes file)<pre><code>/// Structured documents -&gt; a JSON file, written atomically.
class Note {
  Note(this.id, this.text, this.updatedAt);
  final int id;
  final String text;
  final DateTime updatedAt;
  Map&lt;String, dynamic&gt; toJson() =&gt; {'id': id, 'text': text, 'updatedAt': updatedAt.toIso8601String()};
  factory Note.fromJson(Map&lt;String, dynamic&gt; j) =&gt;
      Note(j['id'] as int, j['text'] as String, DateTime.parse(j['updatedAt'] as String));
}

class NotesFile {
  NotesFile(this.file);
  final File file;
  static const schemaVersion = 2;

  Future&lt;List&lt;Note&gt;&gt; load() async {
    if (!await file.exists()) return [];
    final decoded = jsonDecode(await file.readAsString()) as Map&lt;String, dynamic&gt;;
    final migrated = _migrate(decoded);
    return [for (final n in migrated['notes'] as List) Note.fromJson(n as Map&lt;String, dynamic&gt;)];
  }

  Future&lt;void&gt; save(List&lt;Note&gt; notes) async {
    final tmp = File('${file.path}.tmp');
    await tmp.writeAsString(jsonEncode({'version': schemaVersion, 'notes': [for (final n in notes) n.toJson()]}), flush: true);
    await tmp.rename(file.path); // atomic replace on the same filesystem
  }

  /// v1 stored a bare list of {id, text}; v2 wraps it and adds updatedAt.
  Map&lt;String, dynamic&gt; _migrate(Object? data) {
    if (data is Map&lt;String, dynamic&gt; &amp;&amp; data['version'] == schemaVersion) return data;
    if (data is Map&lt;String, dynamic&gt; &amp;&amp; data['version'] == 1) {
      return {
        'version': 2,
        'notes': [
          for (final n in data['notes'] as List)
            {...n as Map&lt;String, dynamic&gt;, 'updatedAt': DateTime.utc(2000).toIso8601String()}
        ],
      };
    }
    throw FormatException('Unknown notes file version: ${data is Map ? data['version'] : data.runtimeType}');
  }
}
</code></pre> <p>Two habits here prevent real data loss:</p> <ul> <li>Atomic save. Writing directly to <code>notes.json</code> and crashing (or being killed) halfway leaves a truncated,   unparseable file. Writing a temp file, flushing it, and renaming it over the original means the file is always   either the old version or the new one.</li> <li>A schema version and migrations. The file records <code>version</code>. Old files are upgraded on load; files from a   newer app version are refused instead of being half-read and then overwritten.</li> </ul> <p>In the app, put the file in the documents directory from <code>path_provider</code>:</p> <pre><code>final dir = await getApplicationDocumentsDirectory(); // package:path_provider
final notes = NotesFile(File('${dir.path}/notes.json'));
</code></pre>

