anim_demo.dart (implicit)<pre><code>import 'package:flutter/material.dart';

/// Implicit: just change a value; the widget animates from old to new.
class ExpandingCard extends StatefulWidget {
  const ExpandingCard({super.key});
  @override
  State&lt;ExpandingCard&gt; createState() =&gt; _ExpandingCardState();
}

class _ExpandingCardState extends State&lt;ExpandingCard&gt; {
  bool open = false;
  @override
  Widget build(BuildContext context) =&gt; GestureDetector(
        onTap: () =&gt; setState(() =&gt; open = !open),
        child: AnimatedContainer(
          key: const Key('card'),
          duration: const Duration(milliseconds: 400),
          curve: Curves.easeInOut,
          width: 200,
          height: open ? 300 : 100,
          color: open ? Colors.indigo : Colors.grey,
        ),
      );
}
</code></pre> <p><code>AnimatedContainer</code> remembers its previous <code>height</code> and <code>color</code> and tweens to the new ones over <code>duration</code> with <code>curve</code>. Its siblings work the same way: <code>AnimatedOpacity</code>, <code>AnimatedAlign</code>, <code>AnimatedPadding</code>, <code>AnimatedDefaultTextStyle</code>, <code>AnimatedSwitcher</code> (cross-fades between two different children), and <code>TweenAnimationBuilder</code> for animating any value of your own to a target.</p>

anim_demo.dart (explicit)<pre><code>/// Explicit: we own an AnimationController and drive it.
class PulsingDot extends StatefulWidget {
  const PulsingDot({super.key});
  @override
  State&lt;PulsingDot&gt; createState() =&gt; PulsingDotState();
}

class PulsingDotState extends State&lt;PulsingDot&gt; with SingleTickerProviderStateMixin {
  late final AnimationController controller = AnimationController(
    vsync: this, // ties ticks to the screen refresh; pauses when off-screen
    duration: const Duration(seconds: 1),
  );
  late final Animation&lt;double&gt; scale =
      Tween&lt;double&gt;(begin: 1, end: 1.5).animate(CurvedAnimation(parent: controller, curve: Curves.easeOut));

  @override
  void initState() {
    super.initState();
    controller.repeat(reverse: true);
  }

  @override
  void dispose() {
    controller.dispose(); // forgetting this leaks a Ticker
    super.dispose();
  }

  @override
  Widget build(BuildContext context) =&gt; AnimatedBuilder(
        animation: scale,
        // child is built once and reused on every tick
        child: Container(width: 20, height: 20, decoration: const BoxDecoration(color: Colors.red, shape: BoxShape.circle)),
        builder: (context, child) =&gt; Transform.scale(scale: scale.value, child: child),
      );
}
</code></pre> <p>The moving parts:</p> <ul> <li><code>AnimationController</code> produces a value from 0.0 to 1.0 over <code>duration</code>, one step per frame. You call <code>forward</code>,   <code>reverse</code>, <code>repeat</code>, <code>stop</code>, <code>animateTo</code>.</li> <li><code>vsync: this</code> with <code>SingleTickerProviderStateMixin</code> gives it a <code>Ticker</code> — a per-frame callback that's muted when   the widget's route isn't visible, so off-screen animations don't burn battery. (Use <code>TickerProviderStateMixin</code> for   several controllers.)</li> <li><code>CurvedAnimation</code> remaps 0→1 through an easing curve; <code>Tween</code> maps 0→1 onto the range you want (1.0→1.5 here).</li> <li><code>AnimatedBuilder</code> rebuilds only its <code>builder</code> on each tick. The <code>child</code> (the red dot) is built once and passed in —   an important optimization for anything non-trivial.</li> <li><code>dispose</code> the controller. Always.</li> </ul> <p>Built-in <code>*Transition</code> widgets (<code>FadeTransition</code>, <code>SlideTransition</code>, <code>ScaleTransition</code>, <code>RotationTransition</code>) take an <code>Animation</code> directly and are even cheaper than an <code>AnimatedBuilder</code>, because they skip the build phase and update the render object's property on each tick.</p>

anim_demo.dart (staggered)<pre><code>/// Staggered: one controller, several intervals.
class StaggeredIntro extends StatefulWidget {
  const StaggeredIntro({super.key});
  @override
  State&lt;StaggeredIntro&gt; createState() =&gt; StaggeredIntroState();
}

class StaggeredIntroState extends State&lt;StaggeredIntro&gt; with SingleTickerProviderStateMixin {
  late final AnimationController c = AnimationController(vsync: this, duration: const Duration(milliseconds: 1000))..forward();
  late final Animation&lt;double&gt; titleOpacity = CurvedAnimation(parent: c, curve: const Interval(0.0, 0.4));
  late final Animation&lt;Offset&gt; bodySlide =
      Tween(begin: const Offset(0, 1), end: Offset.zero).animate(CurvedAnimation(parent: c, curve: const Interval(0.3, 0.8, curve: Curves.easeOut)));
  late final Animation&lt;double&gt; buttonOpacity = CurvedAnimation(parent: c, curve: const Interval(0.7, 1.0));

  @override
  void dispose() {
    c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) =&gt; Column(children: [
        FadeTransition(opacity: titleOpacity, child: const Text('Welcome')),
        SlideTransition(position: bodySlide, child: const Text('Here is how it works')),
        FadeTransition(opacity: buttonOpacity, child: const Text('Get started')),
      ]);
}
</code></pre> <p><code>Interval(0.3, 0.8)</code> means "stay at 0 until the controller reaches 0.3, go to 1 by 0.8, then stay at 1". Overlapping intervals on one controller give you a choreographed sequence that's always in sync and can be reversed as a whole.</p>

