painter_demo.dart<pre><code>import 'dart:math' as math;
import 'package:flutter/material.dart';

/// A sparkline with a highlighted maximum and a filled area under the line.
class Sparkline extends StatelessWidget {
  const Sparkline({super.key, required this.values, this.color = Colors.indigo});
  final List&lt;double&gt; values;
  final Color color;

  @override
  Widget build(BuildContext context) =&gt; Semantics(
        // A canvas is invisible to screen readers unless you describe it.
        label: 'Trend of ${values.length} values, from ${values.first} to ${values.last}, peak ${values.reduce(math.max)}',
        child: CustomPaint(
          size: const Size(double.infinity, 80),
          painter: SparklinePainter(values: values, color: color),
        ),
      );
}

class SparklinePainter extends CustomPainter {
  SparklinePainter({required this.values, required this.color});
  final List&lt;double&gt; values;
  final Color color;

  /// Maps data index/value to canvas coordinates. Public so it can be unit-tested.
  static List&lt;Offset&gt; project(List&lt;double&gt; values, Size size, {double padding = 4}) {
    final minV = values.reduce(math.min), maxV = values.reduce(math.max);
    final range = maxV - minV == 0 ? 1.0 : maxV - minV;
    final w = size.width - 2 * padding, h = size.height - 2 * padding;
    return [
      for (var i = 0; i &lt; values.length; i++)
        Offset(
          padding + (values.length == 1 ? w / 2 : w * i / (values.length - 1)),
          padding + h * (1 - (values[i] - minV) / range), // canvas y grows downward
        ),
    ];
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (values.length &lt; 2) return;
    final pts = project(values, size);

    final line = Path()..moveTo(pts.first.dx, pts.first.dy);
    for (final p in pts.skip(1)) {
      line.lineTo(p.dx, p.dy);
    }
    final area = Path.from(line)
      ..lineTo(pts.last.dx, size.height)
      ..lineTo(pts.first.dx, size.height)
      ..close();

    canvas.drawPath(
      area,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [color.withValues(alpha: 0.35), color.withValues(alpha: 0.0)],
        ).createShader(Offset.zero &amp; size),
    );
    canvas.drawPath(
      line,
      Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2
        ..strokeJoin = StrokeJoin.round,
    );
    final peak = values.indexOf(values.reduce(math.max));
    canvas.drawCircle(pts[peak], 4, Paint()..color = Colors.deepOrange);
    paints++;
  }

  /// Counts paint() calls across all instances, so tests can observe repaints.
  static int paints = 0;

  @override
  bool shouldRepaint(SparklinePainter old) =&gt; old.color != color || !_sameValues(old.values, values);

  static bool _sameValues(List&lt;double&gt; a, List&lt;double&gt; b) {
    if (identical(a, b)) return true;
    if (a.length != b.length) return false;
    for (var i = 0; i &lt; a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }
}
</code></pre> <p>The anatomy of a painter:</p> <ul> <li><code>paint(Canvas canvas, Size size)</code> draws. The origin is the top-left of the <code>CustomPaint</code>'s box, x grows right and   y grows down — hence <code>1 - normalized</code> when mapping values to heights.</li> <li><code>Paint</code> objects carry style: colour or <code>shader</code>, <code>style</code> (fill/stroke), <code>strokeWidth</code>, joins and caps.</li> <li><code>Path</code> builds shapes from <code>moveTo</code>/<code>lineTo</code>/<code>quadraticBezierTo</code>/<code>arcTo</code>… The area fill reuses the line path   (<code>Path.from</code>) and closes it along the bottom edge.</li> <li><code>shouldRepaint(old)</code> is asked whenever a new painter instance is given to the <code>CustomPaint</code>. Return <code>true</code> only if   what you'd draw has changed. Comparing values element by element matters: the caller will usually pass a new <code>List</code> each   build, so <code>!=</code> on the lists would always be <code>true</code>.</li> <li>The math is a pure static function (<code>project</code>) — the most bug-prone part is testable without a canvas.</li> </ul>

