      await Future&lt;void&gt;.delayed(const Duration(milliseconds: 50));
    });
    await tester.pump();
    print('sync while offline: ${tooltip()}');

    server.online = true;
    await tester.runAsync(() async {
      await tester.tap(find.byKey(const Key('sync')));
      await Future&lt;void&gt;.delayed(const Duration(milliseconds: 50));
    });
